/// Render a month-end statement: every invoice, separated by a blank line,
/// followed by `NEXT #<n>` where `<n>` is the number the next issued invoice
/// will receive.
///
/// Rendering only *peeks* at the sequence; it never consumes a number, so
/// printing the same statement twice yields identical output.
pub fn render_invoice_statement(invoices: &[Invoice]) -> String {
    let mut out = String::new();
    for invoice in invoices {
        out.push_str(&render_invoice(invoice));
        out.push('\n');
    }
    out.push_str(&format!("NEXT #{}\n", NEXT_INVOICE.load(Ordering::SeqCst)));
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn issued_invoices_show_their_number() {
        let invoice = Invoice::draft(vec![Line::new("widget", 500)]).issue();
        let text = render_invoice(&invoice);
        assert!(text.starts_with(&format!("INVOICE #{}\n", invoice.number)));
        assert!(text.contains("widget 500\n"));
        assert!(text.ends_with("TOTAL 500\n"));
    }

    #[test]
    fn previewing_a_draft_is_stable() {
        let draft = Invoice::draft(vec![Line::new("widget", 500)]);
        assert_eq!(render_invoice(&draft), render_invoice(&draft));
        assert!(render_invoice(&draft).starts_with("INVOICE DRAFT\n"));
    }

    #[test]
    fn statement_lists_invoices_and_next_number() {
        let a = Invoice::draft(vec![Line::new("widget", 500)]).issue();
        let b = Invoice::draft(vec![Line::new("gadget", 250), Line::new("gizmo", 100)]).issue();
        let text = render_invoice_statement(&[a.clone(), b.clone()]);

        let expected_body = format!("{}\n{}\n", render_invoice(&a), render_invoice(&b));
        assert!(text.starts_with(&expected_body));
        // Invoices are separated by exactly one blank line.
        assert!(text.contains("TOTAL 500\n\nINVOICE #"));

        let next = NEXT_INVOICE.load(Ordering::SeqCst);
        assert!(text.ends_with(&format!("NEXT #{next}\n")));
        assert!(next > b.number);

        // The next-issued invoice really does get the advertised number.
        let c = Invoice::draft(vec![]).issue();
        assert_eq!(c.number, next);
    }

    #[test]
    fn rendering_a_statement_does_not_consume_a_number() {
        let a = Invoice::draft(vec![Line::new("widget", 500)]).issue();
        let before = NEXT_INVOICE.load(Ordering::SeqCst);
        let first = render_invoice_statement(&[a.clone()]);
        let second = render_invoice_statement(&[a]);
        assert_eq!(first, second);
        assert_eq!(NEXT_INVOICE.load(Ordering::SeqCst), before);
    }

    #[test]
    fn empty_statement_only_reports_next_number() {
        let text = render_invoice_statement(&[]);
        assert!(text.starts_with("NEXT #"));
        assert_eq!(text.lines().count(), 1);
    }
}
